            source = "القرآن الكريم — الأعراف: 40، وحديث البراء بن عازب",
            url = "https://quran.com/al-araf/40"
        ),
        PathPassage(
            heading = "4. في القبر (البرزخ): أول منازل الآخرة",
            body = """
                يُوضع الجسد في التراب، ويسمع الميت قرع نعال أهله وأصحابه وهم منصرفون عنه. قال النبي ﷺ: «إِنَّ الْقَبْرَ أَوَّلُ مَنَازِلِ الْآخِرَةِ، فَإِنْ نَجَا مِنْهُ فَمَا بَعْدَهُ أَيْسَرُ مِنْهُ، وَإِنْ لَمْ يَنْجُ مِنْهُ فَمَا بَعْدَهُ أَشَدُّ مِنْهُ» (رواه الترمذي). هنا يأتيه ملكان أسودان أزرقان (منكر ونكير)، فيجلسانه ويسألانه الأسئلة الثلاثة المصيرية: من ربك؟ ما دينك؟ من نبيك؟
                • حال المؤمن في القبر: يثبته الله بالقول الثابت: {يُثَبِّتُ اللَّهُ الَّذِينَ آمَنُوا بِالْقَوْلِ الثَّابِتِ فِي الْحَيَاةِ الدُّنْيَا وَفِي الْآخِرَةِ} [إبراهيم: 27]، فيجيب بثقة: «ربي الله، وديني الإسلام، ونبيي محمد ﷺ». فيُفسح له في قبره مد بصره، ويُفرش من الجنة، ويُلبس من الجنة، ويُفتح له باب إلى الجنة يأتيه من روحها وطيبها، ويأتيه رجل حسن الوجه طيب الريح يقول له: «أَبْشِرْ بِالَّذِي يَسُرُّكَ، أَنَا عَمَلُكَ الصَّالِحُ». فمن شدة ما يرى من النعيم ينادي بلهفة: «رَبِّ أَقِمِ السَّاعَةَ، رَبِّ أَقِمِ السَّاعَةَ حَتَّى أَرْجِعَ إِلَى أَهْلِي وَمَالِي».
                • حال الكافر والمنافق في القبر: يتلعثم ويقول في فزع: «هاه هاه لا أدري، سمعت الناس يقولون شيئًا فقلته!». فيُضيق عليه قبره حتى تختلف أضلاعه، ويُفرش من النار، ويُفتح له باب إلى النار يأتيه من حرها وسمومها، ويأتيه رجل قبيح الوجه منتن الريح يقول له: «أَبْشِرْ بِالَّذِي يَسُوءُكَ، أَنَا عَمَلُكَ الْخَبِيثُ». فمن شدة ما يرى من العذاب والهول، يصرخ بخوف: «رَبِّ لَا تُقِمِ السَّاعَةَ، رَبِّ لَا تُقِمِ السَّاعَةَ».
            """.trimIndent(),
            source = "القرآن الكريم — إبراهيم: 27، وسنن الترمذي وسنن أبي داود",
            url = "https://quran.com/ibrahim/27"
        ),
        PathPassage(
            heading = "5. الانتظار الطويل حتى النفخ في الصور",
            body = """
                تستمر هذه الحياة البرزخية لكل إنسان منذ لحظة موته وحتى يأذن الله بانتهاء الدنيا. فالمؤمن في قبره في روضة من رياض الجنة، ينعم بالطمأنينة، وتُعرض عليه مقعده في الجنة بالغداة والعشي، بينما الكافر والمنافق في حفرة من حفر النار، يُعرض عليه مقعده في النار صباحًا ومساءً في حسرةٍ متجددة: {النَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا ۖ وَيَوْمَ تَقُومُ السَّاعَةُ أَدْخِلُوا آلَ فِرْعَوْنَ أَشَدَّ الْعَذَابِ} [غافر: 46].
                ويبقى الجميع على هذه الحال حتى تأتي اللحظة التي يأمر الله فيها إسرافيل عليه السلام بالنفخ في الصور؛ لتُطوى صفحة الحياة الثانية (البرزخ)، وتبدأ الحياة الأبدية التي لا موت بعدها أبدًا.
            """.trimIndent(),
            source = "القرآن الكريم — غافر: 46",
            url = "https://quran.com/ghafir/46"
        ),
        PathPassage(
            heading = "رسالة ختامية",
            body = """
                تأمل في حالك الآن؛ أنت ما زلت في «الحياة الأولى» حيث تملك القرار، وما زال حبل الأمل في التوبة متصلًا لم يقطعه الموت بعد. تذكر أن القبر إما أن يكون أول محطات نعيمك، أو أول محطات شقائك، وأنت وحدك من يختار أثاث قبره ورفيقه فيه بأعمالك اليوم.
            """.trimIndent()
        )
    )


    /** يعيد المقاطع التحريرية الخاصة بمعرّف الصفحة داخل شاشة «طريق الناجحين». */
    fun passagesFor(id: String): List<PathPassage> = when (id) {
        "eternity" -> eternity
        "failure" -> failure
        "happiness" -> happiness
        "second_life" -> secondLife
        else -> emptyList()
    }
